import type { LodJobPayload, OutputFile } from '../core/types';
import { basename } from '../core/format';

const postLog = (level: 'info' | 'warn' | 'error' | 'debug' | 'progress', text: string) => self.postMessage({ type: 'log', payload: { level, text } });
const postProgress = (value: number, label: string) => self.postMessage({ type: 'progress', payload: { value, label } });

type BuildLodModule = {
  default: (moduleOrPath?: unknown) => Promise<unknown>;
  build_lod: (input: Uint8Array, inputExt: string, opts: unknown) => unknown;
};

let wasmModule: BuildLodModule | undefined;

async function loadWasm(): Promise<BuildLodModule> {
  if (wasmModule) return wasmModule;
  postProgress(10, '加载 build-lod WASM');
  const module = await import('../wasm/build-lod/pkg/build_lod_wasm.js') as BuildLodModule;
  await module.default();
  wasmModule = module;
  return module;
}

function normalizeWasmOutput(value: unknown, baseName: string): OutputFile[] {
  if (!Array.isArray(value)) throw new Error('WASM 返回值格式错误：应为文件数组。');
  return value.map((item: any, index) => {
    const name = String(item.name || item.filename || `${baseName}-${index}.bin`);
    const raw = item.data || item.bytes;
    const data = raw instanceof Uint8Array ? raw : new Uint8Array(raw);
    return { name, data };
  });
}

self.onmessage = async (event: MessageEvent<LodJobPayload>) => {
  try {
    const payload = event.data;
    if (payload.files.length === 0) throw new Error('请先选择至少一个输入文件。');
    const wasm = await loadWasm();
    const outputs: OutputFile[] = [];

    for (let index = 0; index < payload.files.length; index += 1) {
      const file = payload.files[index];
      const extMatch = file.name.match(/\.([^.]+)$/);
      const ext = extMatch ? extMatch[1].toLowerCase() : '';
      const supported = ['ply', 'spz', 'splat', 'ksplat'];
      if (!supported.includes(ext)) throw new Error(`LOD 构建支持 .ply / .spz / .splat / .ksplat，收到：${file.name}`);
      postLog('info', `[${index + 1}/${payload.files.length}] 构建 LOD：${file.name}`);
      const sizeMB = (file.data.byteLength / 1024 / 1024).toFixed(1);
      postLog('info', `文件大小 ${sizeMB} MB，ext=${ext}。WASM LOD 计算中（大文件可能需要数分钟）...`);
      postProgress(24, `解码 + LOD 计算中（${sizeMB} MB，请耐心等待）`);
      const { outputFormat, ...rest } = payload.params;
      const wasmOpts = {
        ...rest,
        output_format: outputFormat,
        filename_base: basename(file.name)
      };
      // 用 BroadcastChannel 实时广播 WASM 内部 console.log，主线程可即时接收
      const bc = new BroadcastChannel('wasm-log');
      const origLog = console.log;
      console.log = (...args: unknown[]) => {
        const msg = args.map(String).join(' ');
        try { bc.postMessage(msg); } catch { /* channel closed */ }
        origLog.apply(console, args);
      };
      const t0 = performance.now();
      let rawResult: unknown;
      try {
        rawResult = wasm.build_lod(new Uint8Array(file.data), ext, wasmOpts);
      } finally {
        console.log = origLog;
        bc.close();
      }
      const t1 = performance.now();
      postLog('info', `WASM LOD 计算完成，耗时 ${((t1 - t0) / 1000).toFixed(1)} 秒`);
      const files = normalizeWasmOutput(rawResult, basename(file.name));
      // 多文件时按输入文件名创建子文件夹，避免产物冲突
      if (payload.files.length > 1) {
        const folder = basename(file.name);
        for (const f of files) f.name = `${folder}/${f.name}`;
      }
      outputs.push(...files);
      postProgress(92, `完成 ${file.name}`);
    }

    self.postMessage({ type: 'done', payload: { files: outputs, summary: `生成 ${outputs.length} 个 LOD 文件` } });
  } catch (error) {
    self.postMessage({ type: 'error', payload: { message: error instanceof Error ? error.message : String(error), stack: error instanceof Error ? error.stack : undefined } });
  }
};
